1  int igraph_read_graph_gml(igraph_t *graph, FILE *instream) {
     2
     3      long int i, p;
     4      long int no_of_nodes = 0, no_of_edges = 0;
     5      igraph_trie_t trie;
     6      igraph_vector_t edges;
     7      igraph_bool_t directed = IGRAPH_UNDIRECTED;
     8      igraph_gml_tree_t *gtree;
     9      long int gidx;
    10      igraph_trie_t vattrnames;
    11      igraph_trie_t eattrnames;
    12      igraph_trie_t gattrnames;
    13      igraph_vector_ptr_t gattrs = IGRAPH_VECTOR_PTR_NULL,
    14                          vattrs = IGRAPH_VECTOR_PTR_NULL, eattrs = IGRAPH_VECTOR_PTR_NULL;
    15      igraph_vector_ptr_t *attrs[3];
    16      long int edgeptr = 0;
    17      igraph_i_gml_parsedata_t context;
    18
    19      attrs[0] = &gattrs; attrs[1] = &vattrs; attrs[2] = &eattrs;
    20
    21      context.eof = 0;
    22      context.tree = 0;
    23
    24      igraph_gml_yylex_init_extra(&context, &context.scanner);
    25      IGRAPH_FINALLY(igraph_gml_yylex_destroy, context.scanner);
    26
    27      igraph_gml_yyset_in(instream, context.scanner);
    28
    29      i = igraph_gml_yyparse(&context);
    30      if (i != 0) {
    31          if (context.errmsg[0] != 0) {
    32              IGRAPH_ERROR(context.errmsg, IGRAPH_PARSEERROR);
    33          } else {
    34              IGRAPH_ERROR("Cannot read GML file", IGRAPH_PARSEERROR);
    35          }
    36      }
    37
    38      IGRAPH_VECTOR_INIT_FINALLY(&edges, 0);
    39
    40      /* Check version, if present, integer and not '1' then ignored */
    41      i = igraph_gml_tree_find(context.tree, "Version", 0);
    42      if (i >= 0 &&
    43          igraph_gml_tree_type(context.tree, i) == IGRAPH_I_GML_TREE_INTEGER &&
    44          igraph_gml_tree_get_integer(context.tree, i) != 1) {
    45          igraph_gml_tree_destroy(context.tree);
    46          IGRAPH_ERROR("Unknown GML version", IGRAPH_UNIMPLEMENTED);
    47          /* RETURN HERE!!!! */
    48      }
    49
    50      /* get the graph */
    51      gidx = igraph_gml_tree_find(context.tree, "graph", 0);
    52      if (gidx == -1) {
    53          IGRAPH_ERROR("No 'graph' object in GML file", IGRAPH_PARSEERROR);
    54      }
    55      if (igraph_gml_tree_type(context.tree, gidx) !=
    56          IGRAPH_I_GML_TREE_TREE) {
    57          IGRAPH_ERROR("Invalid type for 'graph' object in GML file", IGRAPH_PARSEERROR);
    58      }
    59      gtree = igraph_gml_tree_get_tree(context.tree, gidx);
    60
    61      IGRAPH_FINALLY(igraph_i_gml_destroy_attrs, attrs);
    62      igraph_vector_ptr_init(&gattrs, 0);
    63      igraph_vector_ptr_init(&vattrs, 0);
    64      igraph_vector_ptr_init(&eattrs, 0);
    65
    66      IGRAPH_TRIE_INIT_FINALLY(&trie, 0);
    67      IGRAPH_TRIE_INIT_FINALLY(&vattrnames, 0);
    68      IGRAPH_TRIE_INIT_FINALLY(&eattrnames, 0);
    69      IGRAPH_TRIE_INIT_FINALLY(&gattrnames, 0);
    70
    71      /* Is is directed? */
    72      i = igraph_gml_tree_find(gtree, "directed", 0);
    73      if (i >= 0 && igraph_gml_tree_type(gtree, i) == IGRAPH_I_GML_TREE_INTEGER) {
    74          if (igraph_gml_tree_get_integer(gtree, i) == 1) {
    75              directed = IGRAPH_DIRECTED;
    76          }
    77      }
    78
    79      /* Now we go over all objects in the graph and collect the attribute names and
    80         types. Plus we collect node ids. We also do some checks. */
    81      for (i = 0; i < igraph_gml_tree_length(gtree); i++) {
    82          long int j;
    83          char cname[100];
    84          const char *name = igraph_gml_tree_name(gtree, i);
    85          if (!strcmp(name, "node")) {
    86              igraph_gml_tree_t *node;
    87              igraph_bool_t hasid;
    88              no_of_nodes++;
    89              if (igraph_gml_tree_type(gtree, i) != IGRAPH_I_GML_TREE_TREE) {
    90                  IGRAPH_ERROR("'node' is not a list", IGRAPH_PARSEERROR);
    91              }
    92              node = igraph_gml_tree_get_tree(gtree, i);
    93              hasid = 0;
    94              for (j = 0; j < igraph_gml_tree_length(node); j++) {
    95                  const char *name = igraph_gml_tree_name(node, j);
    96                  long int trieid, triesize = igraph_trie_size(&vattrnames);
    97                  IGRAPH_CHECK(igraph_trie_get(&vattrnames, name, &trieid));
    98                  if (trieid == triesize) {
    99                      /* new attribute */
   100                      igraph_attribute_record_t *atrec = igraph_Calloc(1, igraph_attribute_record_t);
   101                      int type = igraph_gml_tree_type(node, j);
   102                      if (!atrec) {
   103                          IGRAPH_ERROR("Cannot read GML file", IGRAPH_ENOMEM);
   104                      }
   105                      IGRAPH_CHECK(igraph_vector_ptr_push_back(&vattrs, atrec));
   106                      atrec->name = strdup(name);
   107                      if (type == IGRAPH_I_GML_TREE_INTEGER || type == IGRAPH_I_GML_TREE_REAL) {
   108                          atrec->type = IGRAPH_ATTRIBUTE_NUMERIC;
   109                      } else {
   110                          atrec->type = IGRAPH_ATTRIBUTE_STRING;
   111                      }
   112                  } else {
   113                      /* already seen, should we update type? */
   114                      igraph_attribute_record_t *atrec = VECTOR(vattrs)[trieid];
   115                      int type1 = atrec->type;
   116                      int type2 = igraph_gml_tree_type(node, j);
   117                      if (type1 == IGRAPH_ATTRIBUTE_NUMERIC && type2 == IGRAPH_I_GML_TREE_STRING) {
   118                          atrec->type = IGRAPH_ATTRIBUTE_STRING;
   119                      }
   120                  }
   121                  /* check id */
   122                  if (!hasid && !strcmp(name, "id")) {
   123                      long int id;
   124                      if (igraph_gml_tree_type(node, j) != IGRAPH_I_GML_TREE_INTEGER) {
   125                          IGRAPH_ERROR("Non-integer node id in GML file", IGRAPH_PARSEERROR);
   126                      }
   127                      id = igraph_gml_tree_get_integer(node, j);
   128                      snprintf(cname, sizeof(cname) / sizeof(char) -1, "%li", id);
   129                      IGRAPH_CHECK(igraph_trie_get(&trie, cname, &id));
   130                      hasid = 1;
   131                  }
   132              }
   133              if (!hasid) {
   134                  IGRAPH_ERROR("Node without 'id' while parsing GML file", IGRAPH_PARSEERROR);
   135              }
   136          } else if (!strcmp(name, "edge")) {
   137              igraph_gml_tree_t *edge;
   138              igraph_bool_t has_source = 0, has_target = 0;
   139              no_of_edges++;
   140              if (igraph_gml_tree_type(gtree, i) != IGRAPH_I_GML_TREE_TREE) {
   141                  IGRAPH_ERROR("'edge' is not a list", IGRAPH_PARSEERROR);
   142              }
   143              edge = igraph_gml_tree_get_tree(gtree, i);
   144              has_source = has_target = 0;
   145              for (j = 0; j < igraph_gml_tree_length(edge); j++) {
   146                  const char *name = igraph_gml_tree_name(edge, j);
   147                  if (!strcmp(name, "source")) {
   148                      has_source = 1;
   149                      if (igraph_gml_tree_type(edge, j) != IGRAPH_I_GML_TREE_INTEGER) {
   150                          IGRAPH_ERROR("Non-integer 'source' for an edge in GML file",
   151                                       IGRAPH_PARSEERROR);
   152                      }
   153                  } else if (!strcmp(name, "target")) {
   154                      has_target = 1;
   155                      if (igraph_gml_tree_type(edge, j) != IGRAPH_I_GML_TREE_INTEGER) {
   156                          IGRAPH_ERROR("Non-integer 'source' for an edge in GML file",
   157                                       IGRAPH_PARSEERROR);
   158                      }
   159                  } else {
   160                      long int trieid, triesize = igraph_trie_size(&eattrnames);
   161                      IGRAPH_CHECK(igraph_trie_get(&eattrnames, name, &trieid));
   162                      if (trieid == triesize) {
   163                          /* new attribute */
   164                          igraph_attribute_record_t *atrec = igraph_Calloc(1, igraph_attribute_record_t);
   165                          int type = igraph_gml_tree_type(edge, j);
   166                          if (!atrec) {
   167                              IGRAPH_ERROR("Cannot read GML file", IGRAPH_ENOMEM);
   168                          }
   169                          IGRAPH_CHECK(igraph_vector_ptr_push_back(&eattrs, atrec));
   170                          atrec->name = strdup(name);
   171                          if (type == IGRAPH_I_GML_TREE_INTEGER || type == IGRAPH_I_GML_TREE_REAL) {
   172                              atrec->type = IGRAPH_ATTRIBUTE_NUMERIC;
   173                          } else {
   174                              atrec->type = IGRAPH_ATTRIBUTE_STRING;
   175                          }
   176                      } else {
   177                          /* already seen, should we update type? */
   178                          igraph_attribute_record_t *atrec = VECTOR(eattrs)[trieid];
   179                          int type1 = atrec->type;
   180                          int type2 = igraph_gml_tree_type(edge, j);
   181                          if (type1 == IGRAPH_ATTRIBUTE_NUMERIC && type2 == IGRAPH_I_GML_TREE_STRING) {
   182                              atrec->type = IGRAPH_ATTRIBUTE_STRING;
   183                          }
   184                      }
   185                  }
   186              } /* for */
   187              if (!has_source) {
   188                  IGRAPH_ERROR("No 'source' for edge in GML file", IGRAPH_PARSEERROR);
   189              }
   190              if (!has_target) {
   191                  IGRAPH_ERROR("No 'target' for edge in GML file", IGRAPH_PARSEERROR);
   192              }
   193          } else {
   194              /* anything to do? Maybe add as graph attribute.... */
   195          }
   196      }
   197
   198      /* check vertex id uniqueness */
   199      if (igraph_trie_size(&trie) != no_of_nodes) {
   200          IGRAPH_ERROR("Node 'id' not unique", IGRAPH_PARSEERROR);
   201      }
   202
   203      /* now we allocate the vectors and strvectors for the attributes */
   204      for (i = 0; i < igraph_vector_ptr_size(&vattrs); i++) {
   205          igraph_attribute_record_t *atrec = VECTOR(vattrs)[i];
   206          int type = atrec->type;
   207          if (type == IGRAPH_ATTRIBUTE_NUMERIC) {
   208              igraph_vector_t *p = igraph_Calloc(1, igraph_vector_t);
   209              atrec->value = p;
   210              IGRAPH_CHECK(igraph_vector_init(p, no_of_nodes));
   211          } else if (type == IGRAPH_ATTRIBUTE_STRING) {
   212              igraph_strvector_t *p = igraph_Calloc(1, igraph_strvector_t);
   213              atrec->value = p;
   214              IGRAPH_CHECK(igraph_strvector_init(p, no_of_nodes));
   215          } else {
   216              IGRAPH_WARNING("A composite attribute ignored");
   217          }
   218      }
   219
   220      for (i = 0; i < igraph_vector_ptr_size(&eattrs); i++) {
   221          igraph_attribute_record_t *atrec = VECTOR(eattrs)[i];
   222          int type = atrec->type;
   223          if (type == IGRAPH_ATTRIBUTE_NUMERIC) {
   224              igraph_vector_t *p = igraph_Calloc(1, igraph_vector_t);
   225              atrec->value = p;
   226              IGRAPH_CHECK(igraph_vector_init(p, no_of_edges));
   227          } else if (type == IGRAPH_ATTRIBUTE_STRING) {
   228              igraph_strvector_t *p = igraph_Calloc(1, igraph_strvector_t);
   229              atrec->value = p;
   230              IGRAPH_CHECK(igraph_strvector_init(p, no_of_edges));
   231          } else {
   232              IGRAPH_WARNING("A composite attribute ignored");
   233          }
   234      }
   235
   236      /* Ok, now the edges, attributes too */
   237      IGRAPH_CHECK(igraph_vector_resize(&edges, no_of_edges * 2));
   238      p = -1;
   239      while ( (p = igraph_gml_tree_find(gtree, "edge", p + 1)) != -1) {
   240          igraph_gml_tree_t *edge;
   241          long int from, to, fromidx = 0, toidx = 0;
   242          char name[100];
   243          long int j;
   244          edge = igraph_gml_tree_get_tree(gtree, p);
   245          for (j = 0; j < igraph_gml_tree_length(edge); j++) {
   246              const char *n = igraph_gml_tree_name(edge, j);
   247              if (!strcmp(n, "source")) {
   248                  fromidx = igraph_gml_tree_find(edge, "source", 0);
   249              } else if (!strcmp(n, "target")) {
   250                  toidx = igraph_gml_tree_find(edge, "target", 0);
   251              } else {
   252                  long int edgeid = edgeptr / 2;
   253                  long int trieidx;
   254                  igraph_attribute_record_t *atrec;
   255                  int type;
   256                  igraph_trie_get(&eattrnames, n, &trieidx);
   257                  atrec = VECTOR(eattrs)[trieidx];
   258                  type = atrec->type;
   259                  if (type == IGRAPH_ATTRIBUTE_NUMERIC) {
   260                      igraph_vector_t *v = (igraph_vector_t *)atrec->value;
   261                      VECTOR(*v)[edgeid] = igraph_i_gml_toreal(edge, j);
   262                  } else if (type == IGRAPH_ATTRIBUTE_STRING) {
   263                      igraph_strvector_t *v = (igraph_strvector_t *)atrec->value;
   264                      const char *value = igraph_i_gml_tostring(edge, j);
   265                      IGRAPH_CHECK(igraph_strvector_set(v, edgeid, value));
   266                  }
   267              }
   268          }
   269          from = igraph_gml_tree_get_integer(edge, fromidx);
   270          to = igraph_gml_tree_get_integer(edge, toidx);
   271          snprintf(name, sizeof(name) / sizeof(char) -1, "%li", from);
   272          IGRAPH_CHECK(igraph_trie_get(&trie, name, &from));
   273          snprintf(name, sizeof(name) / sizeof(char) -1, "%li", to);
   274          IGRAPH_CHECK(igraph_trie_get(&trie, name, &to));
   275          if (igraph_trie_size(&trie) != no_of_nodes) {
   276              IGRAPH_ERROR("Unknown node id found at an edge", IGRAPH_PARSEERROR);
   277          }
   278          VECTOR(edges)[edgeptr++] = from;
   279          VECTOR(edges)[edgeptr++] = to;
   280      }
   281
   282      /* and add vertex attributes */
   283      for (i = 0; i < igraph_gml_tree_length(gtree); i++) {
   284          const char *n;
   285          char name[100];
   286          long int j, k;
   287          n = igraph_gml_tree_name(gtree, i);
   288          if (!strcmp(n, "node")) {
   289              igraph_gml_tree_t *node = igraph_gml_tree_get_tree(gtree, i);
   290              long int iidx = igraph_gml_tree_find(node, "id", 0);
   291              long int id = igraph_gml_tree_get_integer(node, iidx);
   292              snprintf(name, sizeof(name) / sizeof(char) -1, "%li", id);
   293              igraph_trie_get(&trie, name, &id);
   294              for (j = 0; j < igraph_gml_tree_length(node); j++) {
   295                  const char *aname = igraph_gml_tree_name(node, j);
   296                  igraph_attribute_record_t *atrec;
   297                  int type;
   298                  igraph_trie_get(&vattrnames, aname, &k);
   299                  atrec = VECTOR(vattrs)[k];
   300                  type = atrec->type;
   301                  if (type == IGRAPH_ATTRIBUTE_NUMERIC) {
   302                      igraph_vector_t *v = (igraph_vector_t *)atrec->value;
   303                      VECTOR(*v)[id] = igraph_i_gml_toreal(node, j);
   304                  } else if (type == IGRAPH_ATTRIBUTE_STRING) {
   305                      igraph_strvector_t *v = (igraph_strvector_t *)atrec->value;
   306                      const char *value = igraph_i_gml_tostring(node, j);
   307                      IGRAPH_CHECK(igraph_strvector_set(v, id, value));
   308                  }
   309              }
   310          }
   311      }
   312
   313      igraph_gml_tree_destroy(context.tree);
   314
   315      igraph_trie_destroy(&trie);
   316      igraph_trie_destroy(&gattrnames);
   317      igraph_trie_destroy(&vattrnames);
   318      igraph_trie_destroy(&eattrnames);
   319      IGRAPH_FINALLY_CLEAN(4);
   320
   321      IGRAPH_CHECK(igraph_empty_attrs(graph, 0, directed, 0)); /* TODO */
   322      IGRAPH_CHECK(igraph_add_vertices(graph, (igraph_integer_t) no_of_nodes,
   323                                       &vattrs));
   324      IGRAPH_CHECK(igraph_add_edges(graph, &edges, &eattrs));
   325
   326      igraph_i_gml_destroy_attrs(attrs);
   327      igraph_vector_destroy(&edges);
   328      igraph_gml_yylex_destroy(context.scanner);
   329      IGRAPH_FINALLY_CLEAN(3);
   330
   331      return 0;
   332  }
